namespace Sideband.Tests;

// Generated by executing primary Sideband d069122af14880e43607aed0b71add4c7806fbe0.
// GenerateMediaVectors.py records actual LXMF/LXST revisions and canonical source digests.
[Trait("Category", "Integration")]
public sealed class SidebandMediaCodecTests
{
    [Fact]
    public void ImagesFollowActualReferenceDimensionPoliciesAndDecodeActualWebp()
    {
        using var fixture = LoadVectors();
        foreach (var row in fixture.RootElement.GetProperty("images").EnumerateArray())
        {
            var policy = row.GetProperty("policy").GetString() switch
            {
                "lbimg" => SidebandImageQuality.LowBandwidth,
                "defimg" => SidebandImageQuality.Medium,
                _ => SidebandImageQuality.HighResolution,
            };
            var prepared = SidebandMediaCodec.PrepareImage(Convert.FromBase64String(row.GetProperty("input").GetString()!), policy,
                TestContext.Current.CancellationToken);
            Assert.Equal("webp", prepared.Format);
            Assert.Equal(row.GetProperty("width").GetInt32(), prepared.Metadata.Width);
            Assert.Equal(row.GetProperty("height").GetInt32(), prepared.Metadata.Height);
            var validated = SidebandMediaCodec.ValidateImage(prepared.Format, prepared.EncodedBytes, TestContext.Current.CancellationToken);
            Assert.Equal(prepared.Metadata, validated.Metadata);
            var actualReference = SidebandMediaCodec.ValidateImage("webp",
                Convert.FromBase64String(row.GetProperty("encoded").GetString()!), TestContext.Current.CancellationToken);
            Assert.Equal(prepared.Metadata.Width, actualReference.Metadata.Width);
            Assert.Equal(prepared.Metadata.Height, actualReference.Metadata.Height);
            // Skia and Pillow are different encoders/resamplers: byte identity is not claimed.
        }
    }

    [Fact]
    public void ImagesRejectTruncationMismatchedFormatsAndOversizedDimensions()
    {
        using var fixture = LoadVectors();
        var input = Convert.FromBase64String(fixture.RootElement.GetProperty("images")[0].GetProperty("input").GetString()!);
        Assert.Throws<InvalidDataException>(() => SidebandMediaCodec.ValidateImage("webp", input, TestContext.Current.CancellationToken));
        Assert.Throws<InvalidDataException>(() => SidebandMediaCodec.PrepareImage(input.AsSpan(0, 40),
            cancellationToken: TestContext.Current.CancellationToken));
        // A genuine PNG header with enormous dimensions and a corrected IHDR CRC.
        var malicious = input.ToArray();
        BinaryPrimitives.WriteUInt32BigEndian(malicious.AsSpan(16), 100_000);
        BinaryPrimitives.WriteUInt32BigEndian(malicious.AsSpan(20), 100_000);
        BinaryPrimitives.WriteUInt32BigEndian(malicious.AsSpan(29), PngCrc(malicious.AsSpan(12, 17)));
        Assert.Throws<InvalidDataException>(() => SidebandMediaCodec.PrepareImage(malicious,
            cancellationToken: TestContext.Current.CancellationToken));
        Assert.Throws<InvalidDataException>(() => SidebandMediaCodec.ValidateImage("png", malicious, TestContext.Current.CancellationToken));
    }

    [SidebandNativeMediaFact]
    public void Codec2BytesAndFrameTruncationMatchEveryActualSidebandMode()
    {
        using var fixture = LoadVectors();
        var pcm = Convert.FromBase64String(fixture.RootElement.GetProperty("input_pcm").GetString()!);
        var samples = new float[pcm.Length / 2];
        for (var index = 0; index < samples.Length; index++)
            samples[index] = BinaryPrimitives.ReadInt16LittleEndian(pcm.AsSpan(index * 2)) / 32767f;
        foreach (var row in fixture.RootElement.GetProperty("codec2").EnumerateArray())
        {
            var mode = row.GetProperty("mode").GetInt32();
            var reference = Convert.FromHexString(row.GetProperty("encoded").GetString()!);
            var encoded = SidebandMediaCodec.EncodeCodec2(new(samples, 8000, 1), mode, TestContext.Current.CancellationToken);
            Assert.Equal(mode, encoded.Mode);
            Assert.Equal(reference, encoded.EncodedBytes);
            var decoded = SidebandMediaCodec.DecodeCodec2(reference, mode, TestContext.Current.CancellationToken);
            Assert.Equal(row.GetProperty("decoded_samples").GetInt32(), decoded.Samples.Length);
            Assert.Equal(8000, decoded.SampleRate);
            Assert.Equal(1, decoded.Channels);
            // Actual native Codec2 decode includes random excitation; repeated reference
            // decodes are recorded by the generator and PCM byte identity is not claimed.
            Assert.All(decoded.Samples.ToArray(), sample => Assert.True(float.IsFinite(sample)));
            var truncatedTail = SidebandMediaCodec.DecodeCodec2([.. reference, 0x12], mode, TestContext.Current.CancellationToken);
            Assert.Equal(decoded.Samples.Length, truncatedTail.Samples.Length);
        }
    }

    [SidebandNativeMediaFact]
    public async Task ActualReferenceOggDecodesAndCompositionRoundTripsWithoutLxstTail()
    {
        using var fixture = LoadVectors();
        var reference = fixture.RootElement.GetProperty("opus");
        Assert.Equal(SidebandMediaCodec.OpusOggMode, reference.GetProperty("mode").GetInt32());
        var directory = Path.Combine("artifacts", "builds", $"sideband-media-test-{Guid.NewGuid():N}");
        try
        {
            var decoded = await SidebandMediaCodec.DecodeAudioAsync(SidebandMediaCodec.OpusOggMode,
                Convert.FromBase64String(reference.GetProperty("encoded").GetString()!), directory, TestContext.Current.CancellationToken);
            Assert.Equal(48000, decoded.SampleRate);
            Assert.Equal(1, decoded.Channels);
            Assert.Equal(reference.GetProperty("decoded_samples").GetInt32(), decoded.Samples.Length);
            Assert.All(decoded.Samples.ToArray(), sample => Assert.True(float.IsFinite(sample)));
            var input = Enumerable.Range(0, 3600).Select(index => (float)(0.2 * Math.Sin(index * 0.1))).ToArray();
            var prepared = await SidebandMediaCodec.EncodeOggOpusAsync(new(input, 12000, 1), directory, TestContext.Current.CancellationToken);
            Assert.Equal(SidebandMediaCodec.OpusOggMode, prepared.Mode);
            Assert.Equal("OggS"u8.ToArray(), prepared.EncodedBytes[..4]);
            var roundTrip = await SidebandMediaCodec.DecodeOggOpusAsync(prepared.EncodedBytes, directory, TestContext.Current.CancellationToken);
            Assert.Equal(14400, roundTrip.Samples.Length);
            Assert.Contains(roundTrip.Samples.ToArray(), sample => Math.Abs(sample) > 0.05);
            Assert.Empty(Directory.GetFiles(directory));
        }
        finally { if (Directory.Exists(directory)) Directory.Delete(directory, recursive: true); }
    }

    [SidebandNativeMediaFact]
    public async Task OpusCompressedPacketsMatchActualAutomaticBitrateReferenceWithoutAQualityOverride()
    {
        using var fixture = LoadVectors();
        var actual = fixture.RootElement.GetProperty("opus_native12k");
        var pcm = Convert.FromBase64String(actual.GetProperty("input_pcm").GetString()!);
        var samples = new float[pcm.Length / 2];
        for (var index = 0; index < samples.Length; index++)
            samples[index] = BinaryPrimitives.ReadInt16LittleEndian(pcm.AsSpan(index * 2)) / 32767f;
        Assert.Equal(4000, actual.GetProperty("maximum_bytes_per_frame").GetInt32());
        var encoded = await SidebandMediaCodec.EncodeOggOpusAsync(new(samples, 12000, 1),
            "artifacts", TestContext.Current.CancellationToken);
        var packets = OggPackets(encoded.EncodedBytes);
        var referencePackets = actual.GetProperty("packets").EnumerateArray().ToArray();
        Assert.Contains(referencePackets, packet => packet.GetString()!.Length / 2 > 105);
        Assert.Equal(referencePackets.Length + 2, packets.Count);
        for (var index = 0; index < referencePackets.Length; index++)
            Assert.Equal(Convert.FromHexString(referencePackets[index].GetString()!), packets[index + 2]);
        Assert.Equal(actual.GetProperty("preskip").GetInt32() * 4,
            BinaryPrimitives.ReadUInt16LittleEndian(packets[0].AsSpan(10)));
        // The helper's packet bytes match, but native-rate granules do not:
        // reference incorrectly labels 12k samples as 48k; our container preserves duration.
        Assert.Equal(samples.Length, actual.GetProperty("decoded_samples").GetInt32());
    }

    [SidebandNativeMediaFact]
    public async Task AudioCancellationAndMalformedFilesCleanUpOwnedScratchFiles()
    {
        var directory = Path.Combine("artifacts", "builds", $"sideband-media-test-{Guid.NewGuid():N}");
        try
        {
            await Assert.ThrowsAnyAsync<IOException>(() =>
                SidebandMediaCodec.DecodeOggOpusAsync("OggSbogus"u8.ToArray(), directory, TestContext.Current.CancellationToken));
            Assert.Empty(Directory.GetFiles(directory));
            using var cancelled = new CancellationTokenSource();
            cancelled.Cancel();
            await Assert.ThrowsAnyAsync<OperationCanceledException>(() =>
                SidebandMediaCodec.EncodeOggOpusAsync(new(new float[720], 12000, 1), directory, cancelled.Token));
            Assert.Empty(Directory.GetFiles(directory));
        }
        finally { if (Directory.Exists(directory)) Directory.Delete(directory, recursive: true); }
    }

    [SidebandNativeMediaFact]
    public async Task LongOggMetadataAndPartialFinalFrameAreBounded()
    {
        var directory = Path.Combine("artifacts", "builds", $"sideband-media-test-{Guid.NewGuid():N}");
        Directory.CreateDirectory(directory);
        var longPath = Path.Combine(directory, "synthetic-long.ogg");
        try
        {
            await using (var sink = new OpusFileSink(longPath, OpusProfile.AudioLow, appendFinalSilence: false))
                for (var second = 0; second <= SidebandMediaCodec.MaximumAudioDurationSeconds; second++)
                    await sink.WriteAsync(new(new float[12000], 12000, 1), TestContext.Current.CancellationToken);
            var encoded = await File.ReadAllBytesAsync(longPath, TestContext.Current.CancellationToken);
            await Assert.ThrowsAsync<InvalidDataException>(() =>
                SidebandMediaCodec.DecodeOggOpusAsync(encoded, directory, TestContext.Current.CancellationToken));
            Assert.Equal(new[] { longPath }, Directory.GetFiles(directory));
            var shortened = await SidebandMediaCodec.EncodeOggOpusAsync(new(new float[721], 12000, 1),
                directory, TestContext.Current.CancellationToken);
            var partial = await SidebandMediaCodec.DecodeOggOpusAsync(shortened.EncodedBytes,
                directory, TestContext.Current.CancellationToken);
            Assert.Equal(721 * 4, partial.Samples.Length);
        }
        finally { Directory.Delete(directory, recursive: true); }
    }

    private static JsonDocument LoadVectors() => JsonDocument.Parse(
        File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory, "Fixtures", "sideband-media.json")));

    private static List<byte[]> OggPackets(ReadOnlySpan<byte> encoded)
    {
        var packets = new List<byte[]>();
        var current = new List<byte>();
        for (var offset = 0; offset < encoded.Length;)
        {
            Assert.True(encoded.Slice(offset, 4).SequenceEqual("OggS"u8));
            var count = encoded[offset + 26];
            var body = offset + 27 + count;
            for (var segment = 0; segment < count; segment++)
            {
                var length = encoded[offset + 27 + segment];
                current.AddRange(encoded.Slice(body, length).ToArray());
                body += length;
                if (length == 255) continue;
                packets.Add(current.ToArray());
                current.Clear();
            }
            offset = body;
        }
        Assert.Empty(current);
        return packets;
    }

    private static uint PngCrc(ReadOnlySpan<byte> data)
    {
        var crc = uint.MaxValue;
        foreach (var value in data)
        {
            crc ^= value;
            for (var bit = 0; bit < 8; bit++)
                crc = (crc >> 1) ^ ((crc & 1) == 0 ? 0u : 0xedb88320u);
        }
        return ~crc;
    }
}

[Trait("Category", "Unit")]
public sealed class SidebandMediaBoundsTests
{
    [Fact]
    public async Task EncodedLimitsUnsupportedModesAndCancellationFailBeforeNativeLoading()
    {
        Assert.Throws<InvalidDataException>(() => SidebandMediaCodec.PrepareImage([], cancellationToken: TestContext.Current.CancellationToken));
        Assert.Throws<InvalidDataException>(() => SidebandMediaCodec.PrepareImage(new byte[SidebandMediaCodec.MaximumEncodedBytes + 1],
            cancellationToken: TestContext.Current.CancellationToken));
        Assert.Throws<NotSupportedException>(() => SidebandMediaCodec.DecodeCodec2([0], 0x01, TestContext.Current.CancellationToken));
        Assert.Throws<NotSupportedException>(() => SidebandMediaCodec.DecodeCodec2([0], 0xff, TestContext.Current.CancellationToken));
        Assert.Throws<InvalidDataException>(() => SidebandMediaCodec.DecodeCodec2(new byte[24_001], 0x08, TestContext.Current.CancellationToken));
        Assert.Throws<ArgumentException>(() => SidebandMediaCodec.EncodeCodec2(new(new float[320], 48000, 1),
            cancellationToken: TestContext.Current.CancellationToken));
        Assert.Throws<ArgumentException>(() => SidebandMediaCodec.EncodeCodec2(new(new float[320], 8000, 2),
            cancellationToken: TestContext.Current.CancellationToken));
        Assert.Throws<ArgumentException>(() => SidebandMediaCodec.EncodeCodec2(new(new float[80_001], 8000, 1),
            cancellationToken: TestContext.Current.CancellationToken));
        Assert.Throws<ArgumentException>(() => SidebandMediaCodec.EncodeCodec2(new(new float[1], 8000, 1),
            cancellationToken: TestContext.Current.CancellationToken));
        Assert.Throws<ArgumentException>(() => SidebandMediaCodec.EncodeCodec2(new(new float[] { float.NaN }, 8000, 1),
            cancellationToken: TestContext.Current.CancellationToken));
        Assert.Throws<ArgumentException>(() => SidebandMediaCodec.EncodeCodec2(new(new float[] { 1.01f }, 8000, 1),
            cancellationToken: TestContext.Current.CancellationToken));
        await Assert.ThrowsAsync<InvalidDataException>(() =>
            SidebandMediaCodec.DecodeOggOpusAsync("bogus"u8.ToArray(), "artifacts", TestContext.Current.CancellationToken));
        using var cancelled = new CancellationTokenSource();
        cancelled.Cancel();
        Assert.Throws<OperationCanceledException>(() =>
            SidebandMediaCodec.PrepareImage([0], cancellationToken: cancelled.Token));
        Assert.Throws<OperationCanceledException>(() =>
            SidebandMediaCodec.DecodeCodec2([0], 0x08, cancelled.Token));
    }
}

public sealed class SidebandNativeMediaFactAttribute : FactAttribute
{
    public SidebandNativeMediaFactAttribute([CallerFilePath] string? sourceFilePath = null, [CallerLineNumber] int sourceLineNumber = 0)
        : base(sourceFilePath, sourceLineNumber)
    {
        if (Environment.GetEnvironmentVariable("DOTLXST_NATIVE") != "1")
            Skip = "Set DOTLXST_NATIVE=1 with LXST libcodec2, libopusfile and libopusenc installed; actual native audio is required.";
    }
}
